import SwiftUI
import UIKit

/// Your NuviGo logos, embedded so there's no asset file to add in Xcode.
/// One for light mode (white background) and one for dark mode (charcoal background).
enum LogoData {
    static func image(for scheme: ColorScheme) -> UIImage? {
        Data(base64Encoded: scheme == .dark ? darkBase64 : lightBase64).flatMap(UIImage.init(data:))
    }

    /// Just the purple mark on a transparent background (used by the pull-to-refresh indicator).
    static let mark: UIImage? = Data(base64Encoded: markBase64).flatMap(UIImage.init(data:))

    /// The logo's own background color, used behind it on the start-up screen.
    static func background(for scheme: ColorScheme) -> Color {
        scheme == .dark ? Color(red: 54 / 255, green: 58 / 255, blue: 67 / 255) : .white
    }

    private static let lightBase64 = ""

    private static let darkBase64 = ""

    private static let markBase64 = ""
}
